using System.Net;
using System.Net.Http.Json;
using System.Text.Json.Nodes;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Shop.Modules.Credit;
using Shop.Modules.Inventory;
using Shop.Modules.Sales;
using Xunit;
using IdentityContext=Shop.Modules.Identity.IdentityDbContext;
namespace Shop.SqlTests;
public sealed partial class CreditClearanceSqlTests
{
    private static async Task<JsonNode> ReadUpfront79(HttpResponseMessage response)
    {
        using(response){Assert.True(response.IsSuccessStatusCode,"Synthetic upfront HTTP "+(int)response.StatusCode);var raw=await response.Content.ReadAsStringAsync();Assert.Contains("no-store",response.Headers.CacheControl!.ToString());Assert.Contains("noindex",response.Headers.GetValues("X-Robots-Tag").Single());if(Environment.GetEnvironmentVariable("SHOP_UPFRONT_CORRECTION_WIRE_DIR")is{Length:>0}dir){Directory.CreateDirectory(dir);var id=Id();var request=response.RequestMessage!;JsonNode? body=request.Options.TryGetValue(new HttpRequestOptionsKey<string>("SyntheticUpfrontBody"),out var posted)?JsonNode.Parse(posted):null;await File.WriteAllTextAsync(Path.Combine(dir,id+".json"),raw);await File.WriteAllTextAsync(Path.Combine(dir,id+".meta.json"),JsonSerializer.Serialize(new{actualSqlHttpResponse=true,syntheticQaOnly=true,status=(int)response.StatusCode,method=request.Method.Method,path=request.RequestUri!.PathAndQuery,requestBody=body}));}return JsonNode.Parse(raw)!;}
    }
    private static async Task<JsonNode> Upfront(HttpClient f,Scenario s)=>await ReadUpfront79(await f.GetAsync(Base(s)+"/upfront"));
    private static CreditUpfrontInput Amendment(JsonNode page,string action,DateTimeOffset? occurred=null)=>new(action,V(page,"orderVersion"),V(page,"scheduleVersion"),V(page["current"]!,"version"),action=="ConfirmReceipt"?"SYNTHETIC-CORRECTED-REFERENCE":"","Synthetic committed correction only; no real person or funds",occurred??DateTimeOffset.UtcNow,true,false,true);
    private static async Task<JsonNode> Amend(HttpClient f,Scenario s,CreditUpfrontInput input,string? command=null){var raw=JsonSerializer.Serialize(input,new JsonSerializerOptions(JsonSerializerDefaults.Web));var request=new HttpRequestMessage(HttpMethod.Post,Base(s)+"/upfront/commands/"+(command??Id())){Content=new StringContent(raw,System.Text.Encoding.UTF8,"application/json")};request.Options.Set(new HttpRequestOptionsKey<string>("SyntheticUpfrontBody"),raw);return await ReadUpfront79(await f.SendAsync(request));}
    [Fact]public async Task CommittedUpfrontCorrectionRequiresExplicitReviewAndFreshFinalClearanceWithoutChangingStockOrDeadline()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;await Write(f,s,await Page(f,s));var original=await Upfront(f,s);Assert.True(original["canRevoke"]!.GetValue<bool>());var priorOccurred=original["current"]!["occurredAt"]!.GetValue<DateTimeOffset>();var revoke=Amendment(original,"RevokeConfirmation");
        using(var legacy=await f.PostAsJsonAsync(Base(s)+"/upfront/commands/"+Id(),revoke with{AcknowledgedCommittedOrder=false}))Assert.Equal(HttpStatusCode.Conflict,legacy.StatusCode);
        var command=Id();var revoked=await Amend(f,s,revoke,command);Assert.True(revoked["event"]!["acknowledgedCommittedOrder"]!.GetValue<bool>());Assert.False((await Page(f,s))["effective"]!.GetValue<bool>());var current=await Upfront(f,s);var action=V(current,"requiredAmountRial")=="0"?"ConfirmNoUpfrontDue":"ConfirmReceipt";Assert.True(current[action=="ConfirmReceipt"?"canConfirmReceipt":"canConfirmNoUpfrontDue"]!.GetValue<bool>());
        var restored=await Amend(f,s,Amendment(current,action,priorOccurred));Assert.Equal(original["requiredAmountRial"]!.ToJsonString(),restored["event"]!["summary"]!["acknowledgedAmountRial"]!.ToJsonString());Assert.False((await Page(f,s))["effective"]!.GetValue<bool>());var refreshed=await Write(f,s,await Page(f,s));Assert.False(refreshed["initialCommit"]!.GetValue<bool>());Assert.True((await Page(f,s))["effective"]!.GetValue<bool>());
        await ReadUpfront79(await f.GetAsync(Base(s)+"/upfront/history"));var replay=await Amend(f,s,revoke,command);Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(revoked["event"]!.ToJsonString(),replay["event"]!.ToJsonString());var owned=await ReadUpfront79(await customer.GetAsync("/api/credit/orders/"+s.Id+"/upfront"));Assert.Null(owned["current"]!["acknowledgedCommittedOrder"]);Assert.DoesNotContain("SYNTHETIC-CORRECTED",owned.ToJsonString());var detail=await CreditOrderQa.Read(await customer.GetAsync("/api/credit-orders/"+s.Id));Assert.Equal(s.Order["summary"]!["expiresAt"]!.ToJsonString(),detail["order"]!["summary"]!["expiresAt"]!.ToJsonString());
        await using var scope=sql.Factory.Services.CreateAsyncScope();var stock=await scope.ServiceProvider.GetRequiredService<InventoryDbContext>().Stock.SingleAsync(x=>x.VariantId==s.Variant);Assert.Equal(1,stock.Reserved);var sales=scope.ServiceProvider.GetRequiredService<SalesDbContext>();Assert.Equal(0,await sales.OrderCashPayments.CountAsync());Assert.Equal(0,await sales.Orders.CountAsync(x=>x.State==OrderState.Paid));Assert.Equal(1,await scope.ServiceProvider.GetRequiredService<CreditDbContext>().PurchaseScopeUses.CountAsync(x=>x.OrderId==s.Id));
    }
    [Fact]public async Task CommittedCorrectionAuditFailureRollsBackAndCompetingReconfirmationHasOneEvent()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;await Write(f,s,await Page(f,s));var page=await Upfront(f,s);var input=Amendment(page,"RevokeConfirmation");var command=Id();await using(var scope=sql.Factory.Services.CreateAsyncScope())await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] WITH NOCHECK ADD CONSTRAINT CK_QA_UpfrontCommittedAudit CHECK ([Action]<>'CREDIT_UPFRONT_REVOKECONFIRMATION')");
        try{using var denied=await f.PostAsJsonAsync(Base(s)+"/upfront/commands/"+command,input);Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);}finally{await using var scope=sql.Factory.Services.CreateAsyncScope();await scope.ServiceProvider.GetRequiredService<IdentityContext>().Database.ExecuteSqlRawAsync("ALTER TABLE [identity].[Audit] DROP CONSTRAINT CK_QA_UpfrontCommittedAudit");}
        Assert.Equal(page["current"]!.ToJsonString(),(await Upfront(f,s))["current"]!.ToJsonString());Assert.True((await Page(f,s))["effective"]!.GetValue<bool>());using(var missing=await f.GetAsync(Base(s)+"/upfront/commands/"+command))Assert.Equal(HttpStatusCode.NotFound,missing.StatusCode);await Amend(f,s,input,command);var current=await Upfront(f,s);var body=Amendment(current,V(current,"requiredAmountRial")=="0"?"ConfirmNoUpfrontDue":"ConfirmReceipt");var attempts=await Task.WhenAll(f.PostAsJsonAsync(Base(s)+"/upfront/commands/"+Id(),body),f.PostAsJsonAsync(Base(s)+"/upfront/commands/"+Id(),body));Assert.Single(attempts,x=>x.IsSuccessStatusCode);Assert.Single(attempts,x=>x.StatusCode==HttpStatusCode.Conflict);foreach(var response in attempts)response.Dispose();await using var check=sql.Factory.Services.CreateAsyncScope();Assert.Equal(3,await check.ServiceProvider.GetRequiredService<CreditDbContext>().UpfrontEvents.CountAsync(x=>x.OrderId==s.Id));
    }
    [Fact]public async Task CommittedCorrectionAndDispatchRaceShareTheOrderGateAndCannotBothCommit()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var warehouse=await Staff("Administrator");var s=await Ready(f,reviewer);using var customer=s.Customer;await Write(f,s,await Page(f,s));var shipping="/api/admin/orders/"+s.Id+"/shipment/commands";await CreditOrderQa.Read(await warehouse.PostAsJsonAsync(shipping,ShipmentInput(await Shipment(warehouse,s),"pack")));var packed=await Shipment(warehouse,s);var upfront=await Upfront(f,s);var attempts=await Task.WhenAll(f.PostAsJsonAsync(Base(s)+"/upfront/commands/"+Id(),Amendment(upfront,"RevokeConfirmation")),warehouse.PostAsJsonAsync(shipping,ShipmentInput(packed,"dispatch")));Assert.Single(attempts,x=>x.IsSuccessStatusCode);Assert.Single(attempts,x=>x.StatusCode==HttpStatusCode.Conflict);var revoked=attempts[0].IsSuccessStatusCode;foreach(var response in attempts)response.Dispose();var status=await Shipment(warehouse,s);if(revoked){Assert.False(status.CanDispatch);Assert.Equal("packed",status.Shipment!.State);}else{Assert.Equal("dispatched",status.Shipment!.State);Assert.False((await Upfront(f,s))["canRevoke"]!.GetValue<bool>());}
    }
    [Fact]public async Task CommittedCorrectionIsBlockedAfterDispatchAndDeliveryButHistoricalReceiptsRemainReadable()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");using var warehouse=await Staff("Administrator");var s=await Ready(f,reviewer);using var customer=s.Customer;await Write(f,s,await Page(f,s));var up=await Upfront(f,s);var command=Id();var revoked=await Amend(f,s,Amendment(up,"RevokeConfirmation"),command);up=await Upfront(f,s);await Amend(f,s,Amendment(up,V(up,"requiredAmountRial")=="0"?"ConfirmNoUpfrontDue":"ConfirmReceipt"));await Write(f,s,await Page(f,s));var shipping="/api/admin/orders/"+s.Id+"/shipment/commands";await CreditOrderQa.Read(await warehouse.PostAsJsonAsync(shipping,ShipmentInput(await Shipment(warehouse,s),"pack")));await CreditOrderQa.Read(await warehouse.PostAsJsonAsync(shipping,ShipmentInput(await Shipment(warehouse,s),"dispatch")));up=await Upfront(f,s);Assert.Contains("shipment_already_dispatched",up["blockers"]!.AsArray().Select(x=>x!.GetValue<string>()));Assert.False(up["canRevoke"]!.GetValue<bool>());using(var denied=await f.PostAsJsonAsync(Base(s)+"/upfront/commands/"+Id(),Amendment(up,"RevokeConfirmation")))Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);var receipt=await ReadUpfront79(await f.GetAsync(Base(s)+"/upfront/commands/"+command));Assert.Equal(revoked["event"]!.ToJsonString(),receipt["event"]!.ToJsonString());await CreditOrderQa.Read(await warehouse.PostAsJsonAsync(shipping,ShipmentInput(await Shipment(warehouse,s),"deliver")));up=await Upfront(f,s);using(var denied=await f.PostAsJsonAsync(Base(s)+"/upfront/commands/"+Id(),Amendment(up,"RevokeConfirmation")))Assert.Equal(HttpStatusCode.Conflict,denied.StatusCode);
    }
    [Fact]public async Task CommittedZeroUpfrontCanOnlyReconfirmNoFundsDueAndCannotInventAReceipt()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer,zero:true);using var customer=s.Customer;await Write(f,s,await Page(f,s));var up=await Upfront(f,s);Assert.Equal("0",V(up,"requiredAmountRial"));await Amend(f,s,Amendment(up,"RevokeConfirmation"));up=await Upfront(f,s);Assert.False(up["canConfirmReceipt"]!.GetValue<bool>());Assert.True(up["canConfirmNoUpfrontDue"]!.GetValue<bool>());using(var wrong=await f.PostAsJsonAsync(Base(s)+"/upfront/commands/"+Id(),Amendment(up,"ConfirmReceipt")))Assert.Equal(HttpStatusCode.Conflict,wrong.StatusCode);var restored=await Amend(f,s,Amendment(up,"ConfirmNoUpfrontDue"));Assert.Equal("NoUpfrontDue",V(restored["event"]!["summary"]!,"state"));Assert.Equal("0",V(restored["event"]!["summary"]!,"acknowledgedAmountRial"));Assert.False((await Page(f,s))["effective"]!.GetValue<bool>());await Write(f,s,await Page(f,s));Assert.True((await Page(f,s))["effective"]!.GetValue<bool>());
    }
    [Fact]public async Task LegacyReceiptWithoutCommittedFlagAndOriginalCommandHashRemainReplayableAfterCommitment()
    {
        using var f=await Staff("FinanceManager");using var reviewer=await Staff("CreditReviewer");var s=await Ready(f,reviewer);using var customer=s.Customer;var up=await Upfront(f,s);var eventId=V(up["current"]!,"id");string command;await using(var scope=sql.Factory.Services.CreateAsyncScope()){var db=scope.ServiceProvider.GetRequiredService<CreditDbContext>();var row=await db.UpfrontCommands.SingleAsync(x=>x.EventId==eventId);command=row.CommandId;var protection=scope.ServiceProvider.GetRequiredService<ICreditUpfrontProtection>();var raw=protection.Unprotect("receipt",row.ActorId,row.OrderId,row.CommandId,row.ProtectedResult);Assert.DoesNotContain("acknowledgedCommittedOrder",raw);}
        var receipt=await ReadUpfront79(await f.GetAsync(Base(s)+"/upfront/commands/"+command));var e=receipt["event"]!;Assert.False(e.AsObject().ContainsKey("acknowledgedCommittedOrder"));var original=new CreditUpfrontInput(V(e["summary"]!,"action"),V(e,"orderVersion"),V(e,"scheduleVersion"),e["previousVersion"]?.GetValue<string>(),V(e,"reference"),V(e,"note"),e["summary"]!["occurredAt"]!.GetValue<DateTimeOffset>(),true,e["acknowledgedClosedOrder"]!.GetValue<bool>());await Write(f,s,await Page(f,s));var replay=await Amend(f,s,original,command);Assert.True(replay["replayed"]!.GetValue<bool>());Assert.Equal(receipt["event"]!.ToJsonString(),replay["event"]!.ToJsonString());await using var check=sql.Factory.Services.CreateAsyncScope();Assert.Equal(1,await check.ServiceProvider.GetRequiredService<CreditDbContext>().UpfrontEvents.CountAsync(x=>x.OrderId==s.Id));
    }

}
